/* ============ AETHERIA — mobile dark fantasy UI ============ */
* { margin:0; padding:0; box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
html,body { height:100%; overflow:hidden; background:#07090f; }
body { font-family:"Trebuchet MS","Segoe UI",Verdana,sans-serif; color:#e8ecf5; user-select:none; -webkit-user-select:none; touch-action:none; overscroll-behavior:none; }
#app { position:fixed; inset:0; }
.hidden { display:none !important; }
button { font-family:inherit; color:inherit; border:none; background:none; cursor:pointer; }

/* ---------- screens ---------- */
.screen { position:absolute; inset:0; }
#loadingScreen { display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px;
  background:radial-gradient(ellipse at 50% 30%, #17213d 0%, #07090f 75%); z-index:50; }
.load-title { font-size:52px; font-weight:900; letter-spacing:12px; color:#ffd77a; text-shadow:0 0 24px #b7791f, 0 2px 0 #4a3208; }
.load-sub { color:#9fb4dd; letter-spacing:4px; font-size:13px; }
.load-bar { width:min(64vw,320px); height:10px; border-radius:6px; background:#101728; border:1px solid #2b3a5e; overflow:hidden; }
#loadFill { height:100%; width:0%; background:linear-gradient(90deg,#ffd77a,#ff9d3c); transition:width .2s; }
.load-text { font-size:12px; color:#7d91bd; }

#menuScreen { display:flex; flex-direction:column; align-items:center; justify-content:center; gap:10px;
  background:radial-gradient(ellipse at 50% 20%, #1c2440 0%, #07090f 70%); z-index:40; }
.menu-title { font-size:60px; font-weight:900; letter-spacing:14px; display:flex; }
.menu-title span { animation:soul 3s ease-in-out infinite; text-shadow:0 0 26px currentColor; }
.menu-title .a1{color:#5da8ff}.menu-title .a2{color:#8ff5ff}.menu-title .a3{color:#ffd77a}.menu-title .a4{color:#ff8f5d}
.menu-title .a5{color:#b565ff}.menu-title .a6{color:#5fd35f}.menu-title .a7{color:#ff4d94}.menu-title .a8{color:#e8ecf5}
@keyframes soul { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-6px)} }
.menu-sub { color:#9fb4dd; letter-spacing:5px; font-size:13px; margin-bottom:20px; }
.menu-btns { display:flex; flex-direction:column; gap:12px; width:min(66vw,280px); }
.mbtn { padding:14px 20px; border-radius:12px; font-size:16px; font-weight:700; letter-spacing:2px; }
.mbtn.primary { background:linear-gradient(180deg,#2b3f6e,#182档档档档); }
.menu-note { position:absolute; bottom:14px; font-size:10px; color:#5c6f96; }

/* generic button styling */
.mbtn.primary, .cbtn.primary, .btn.primary {
  background:linear-gradient(180deg,#3d5a9e,#22345e); border:1px solid #5a7fd4; color:#fff;
  box-shadow:0 3px 0 #16223d, 0 0 14px rgba(90,127,212,.35);
}
.mbtn.primary:active, .cbtn.primary:active,.btn.primary:active { transform:translateY(2px); box-shadow:0 1px 0 #16223d; }
.mbtn.danger,.btn.danger { background:linear-gradient(180deg,#7e2b34,#4d1a20); border:1px solid #b05058; }
.cbtn.ghost,.btn.ghost { background:#141c2e; border:1px solid #33445f; color:#a9bce0; }

/* ---------- character creation ---------- */
#createScreen { background:radial-gradient(ellipse at 50% 35%, #232c4d 0%, #0a0d18 75%); z-index:30; display:flex; flex-direction:column; }
.create-head { padding:16px 18px 8px; }
.create-step { font-size:11px; letter-spacing:3px; color:#8fa4cf; }
.create-title { font-size:22px; font-weight:800; color:#ffd77a; letter-spacing:1px; margin-top:2px; }
.create-body { flex:1; overflow-y:auto; padding:8px 14px 90px; touch-action:pan-y; }
.create-foot { position:absolute; left:0; right:0; bottom:0; display:flex; gap:10px; padding:12px 14px 16px; justify-content:space-between;
  background:linear-gradient(0deg, rgba(7,9,15,.95), rgba(7,9,15,0)); }
.cbtn { padding:13px 24px; border-radius:12px; font-weight:800; font-size:15px; letter-spacing:1px; min-width:110px; }

.row { display:flex; gap:8px; margin-bottom:12px; flex-wrap:wrap; }
.field { width:100%; padding:14px; border-radius:10px; background:#10182b; border:1px solid #31446b; color:#fff; font-size:17px; outline:none; }
.cc-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
.cc-card { background:#10182b; border:1px solid #31446b; border-radius:14px; padding:14px 10px; text-align:center; transition:.15s; }
.cc-card.sel { border-color:gold; background:#1c2650; box-shadow:0 0 12px rgba(255,215,122,.35); }
.cc-card .cc-ico { font-size:34px; }
.cc-card .cc-name { font-weight:800; margin-top:6px; color:#ffd77a; }
.cc-card .cc-desc { font-size:11px; color:#9db1d8; margin-top:4px; line-height:1.35; }
.opt-chip { padding:9px 13px; border-radius:999px; background:#10182b; border:1px solid #31446b; font-size:13px; color:#c7d4ef; }
.opt-chip.sel { background:#2c3d6e; border-color:#7fa2ff; color:#fff; font-weight:700; }
.swatch { width:34px; height:34px; border-radius:50%; border:2px solid #31446b; }
.swatch.sel { border-color:#fff; box-shadow:0 0 8px #fff8; }
.cc-preview { display:flex; justify-content:center; margin:4px 0 10px; }
.cc-preview canvas { background:radial-gradient(ellipse at 50% 60%, #2a3560 0%, #131a30 75%); border-radius:18px; border:1px solid #3a4f7e; image-rendering:pixelated; }
.stat-line { font-size:12px; color:#a9bce0; line-height:1.5; }
.stat-line b { color:#ffd77a; }

/* ---------- game HUD ---------- */
#gameCanvas { position:absolute; inset:0; width:100%; height:100%; }
.hud-top { position:absolute; top:0; left:0; right:0; display:flex; justify-content:space-between; padding:8px 8px 0; pointer-events:none; }
.hud-top > * { pointer-events:auto; }
.hud-left { flex:1; max-width:46%; }
.barrow { margin-bottom:4px; }
.bar { position:relative; height:16px; border-radius:8px; background:#10131f; border:1px solid #000; overflow:hidden; box-shadow:0 1px 3px #000a; }
.bar span { position:absolute; inset:0; display:flex; align-items:center; justify-content:center; font-size:10px; font-weight:700; text-shadow:0 1px 2px #000; }
.bar>div { height:100%; transition:width .25s; border-radius:7px; }
.bar.hp>div { background:linear-gradient(180deg,#ff5a5a,#c22); }
.bar.mp>div { background:linear-gradient(180deg,#4d9bff,#2456c9); }
.bar.xp { height:9px; border-radius:5px; margin-top:6px; width:80%; }
.bar.xp>div { background:linear-gradient(180deg,#ffd77a,#d99a2b); }
.bar.xp span { font-size:8px; }
.currency { margin-top:5px; display:flex; gap:10px; font-size:12px; font-weight:800; }
.cur { display:inline-flex; align-items:center; gap:4px; background:#0e1422cc; padding:3px 9px; border-radius:10px; border:1px solid #2b3a5e; }
.cur.gem::before { content:'💎'; font-size:11px; }

.hud-right { display:flex; flex-direction:column; align-items:flex-end; gap:5px; }
.minimap-wrap { position:relative; }
#minimap { background:#0a0e19; border:1px solid #33445f; border-radius:8px; opacity:.92; }
.region-name { position:absolute; top:2px; left:0; right:0; text-align:center; font-size:9px; font-weight:800; letter-spacing:1px; color:#ffd77a; text-shadow:0 1px 2px #000; }
.top-icons { display:flex; gap:6px; margin-top:2px; }
.ibtn { width:34px; height:34px; border-radius:10px; background:#101a2ecc; border:1px solid #33445f; font-size:16px; display:flex; align-items:center; justify-content:center; }
.ibtn:active { background:#2c3d6e; }
.quest-tracker { max-width:180px; font-size:10px; color:#cff3c9; background:#0e142277; padding:4px 7px; border-radius:8px; line-height:1.4; text-shadow:0 1px 2px #000; }
.quest-tracker b { color:#ffd77a; }

.hud-bottom { position:absolute; bottom:0; left:0; right:0; display:flex; align-items:flex-end; justify-content:space-between; padding:0 10px calc(14px + env(safe-area-inset-bottom)); pointer-events:none; }
.joystick-zone { width:44%; max-width:220px; height:170px; position:relative; pointer-events:auto; }
.joy-base { position:absolute; left:18px; bottom:14px; width:110px; height:110px; border-radius:50%; background:#101a2e88; border:2px solid #33445f; }
.joy-stick { position:absolute; left:50%; top:50%; width:48px; height:48px; border-radius:50%; background:#5a7fd4aa; border:2px solid #8fb0ff; transform:translate(-50%,-50%); transition:transform .05s; }
.action-cluster { display:flex; flex-direction:column; align-items:flex-end; gap:8px; pointer-events:auto; }
.small-actions { display:flex; gap:8px; }
.abtn { position:relative; background:#131c30cc; border:1px solid #43598a; border-radius:50%; display:flex; align-items:center; justify-content:center; flex-direction:column; }
.abtn:active { background:#31446b; transform:scale(.94); }
.abtn span { font-size:20px; filter:drop-shadow(0 1px 1px #000); }
.abtn i { position:absolute; inset:0; display:flex; align-items:center; justify-content:center; font-style:normal; font-weight:900; color:#fff; font-size:15px; text-shadow:0 1px 3px #000; }
.abtn em { position:absolute; bottom:2px; font-style:normal; font-size:8px; letter-spacing:1px; color:#cfe1ff; }
.abtn b { position:absolute; top:-4px; right:-2px; background:#e0b037; color:#26180a; font-size:10px; min-width:17px; height:17px; line-height:17px; border-radius:9px; padding:0 2px; font-weight:900; }
.abtn b.zero { background:#5c6f96; color:#1a2233; }
.abtn.small { width:46px; height:46px; }
#btnMount.summoned { border-color:#7fe07f; box-shadow:0 0 10px #3fa06a88; }
#btnAuto.on { border-color:#ffd77a; box-shadow:0 0 10px #d99a2b88; }
.main-actions { display:flex; align-items:flex-end; gap:12px; }
.abtn.skill { width:74px; height:74px; border-color:#b565ff; background:linear-gradient(180deg,#3a1d5ecc,#1d0f38cc); }
.abtn.skill.cd { filter:grayscale(.8); opacity:.7; }
.abtn.skill i { font-size:22px; }
.abtn.skill.ready { box-shadow:0 0 14px #b565ff66; animation:pulse 1.6s infinite; }
@keyframes pulse { 50% { box-shadow:0 0 22px #b565ffaa; } }
.abtn.attack { width:88px; height:88px; background:linear-gradient(180deg,#5c2430cc,#2b1016cc); border-color:#b05058; }
.abtn.interact { width:52px; height:52px; margin-right:4px; border-radius:14px; border-color:#7fa2ff; }
.abtn.interact i { position:static; margin-top:2px; font-size:9px; }

#toastWrap { position:absolute; top:34%; left:0; right:0; display:flex; flex-direction:column; align-items:center; gap:6px; pointer-events:none; }
.toast { background:#0e1422ee; border:1px solid #43598a; color:#fff; padding:8px 16px; border-radius:10px; font-size:13px; font-weight:700; box-shadow:0 4px 14px #000a; animation:toast 2.6s forwards; }
.toast.good { border-color:#5fd35f; } .toast.bad { border-color:#ff5a5a; } .toast.gold { border-color:#ffd77a; }
@keyframes toast { 0%{opacity:0;transform:translateY(8px)} 10%{opacity:1;transform:translateY(0)} 80%{opacity:1} 100%{opacity:0;transform:translateY(-6px)} }
#pickupLog { position:absolute; left:8px; bottom:190px; display:flex; flex-direction:column-reverse; gap:3px; pointer-events:none; }
.pick { font-size:10px; font-weight:700; text-shadow:0 1px 2px #000; animation:pick 2.4s forwards; }
@keyframes pick { 0%{opacity:0;transform:translateX(-6px)} 12%{opacity:1;transform:none} 75%{opacity:1} 100%{opacity:0} }

/* ---------- modal / panels ---------- */
.modal { position:absolute; inset:0; background:#04060cdd; z-index:60; display:flex; align-items:flex-end; justify-content:center; }
.modal-box { width:100%; max-width:520px; max-height:88%; background:linear-gradient(180deg,#131a2e,#0d1220); border:1px solid #3a4f7e; border-bottom:none;
  border-radius:18px 18px 0 0; display:flex; flex-direction:column; overflow:hidden; animation:slideup .2s; }
@keyframes slideup { from{transform:translateY(24px);opacity:.4} }
.panel-head { display:flex; align-items:center; padding:12px 14px 8px; gap:8px; }
.panel-title { flex:1; font-size:16px; font-weight:800; letter-spacing:1px; color:#ffd77a; }
.panel-x { width:34px; height:34px; border-radius:9px; background:#2b3a5e; font-size:16px; color:#fff; }
.tabs { display:flex; gap:4px; padding:0 10px 6px; overflow-x:auto; }
.tab { padding:8px 13px; border-radius:9px; background:#101828; border:1px solid #2b3a5e; font-size:12px; color:#9db1d8; white-space:nowrap; }
.tab.on { background:#2c3d6e; border-color:#7fa2ff; color:#fff; font-weight:800; }
.panel-body { flex:1; overflow-y:auto; padding:10px 12px 20px; touch-action:pan-y; }

.item-row { display:flex; align-items:center; gap:9px; background:#101828; border:1px solid #263450; border-radius:11px; padding:8px 10px; margin-bottom:7px; }
.item-ico { width:38px; height:38px; border-radius:8px; display:flex; align-items:center; justify-content:center; font-size:19px; background:#0b0f1c; border:1px solid currentColor; flex-shrink:0; }
.item-main { flex:1; min-width:0; }
.item-name { font-size:12px; font-weight:800; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.item-sub { font-size:10px; color:#8fa4cf; margin-top:2px; line-height:1.35; }
.item-stats { font-size:10px; color:#9fd4a8; margin-top:2px; line-height:1.4; }
.item-btns { display:flex; flex-direction:column; gap:4px; }
.min-btn { padding:6px 10px; border-radius:8px; background:#2b3a5e; font-size:11px; font-weight:800; color:#fff; white-space:nowrap; }
.min-btn.gold { background:#8a6a1c; } .min-btn.danger { background:#6d2830; } .min-btn.green { background:#2c6e3f; }
.slot-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; margin-bottom:12px; }
.slot-cell { aspect-ratio:1; border-radius:12px; background:#0e1526; border:1px dashed #33445f; display:flex; flex-direction:column; align-items:center; justify-content:center; position:relative; }
.slot-cell .s-ico { font-size:22px; opacity:.85; }
.slot-cell .s-name { font-size:10px; font-weight:800; text-align:center; padding:0 2px; line-height:1.2; max-width:100%; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.slot-cell .s-sub { font-size:9px; color:#8fa4cf; }
.empty-phase { text-align:center; color:#5c6f96; font-size:12px; padding:30px 10px; line-height:1.6; }
.price-badge { font-size:10px; color:#ffd77a; font-weight:800; position:absolute; top:3px; right:6px; text-shadow:0 1px 2px #000; }

/* ---------- NPC dialog ---------- */
.dialog { position:absolute; inset:0; z-index:55; display:flex; align-items:flex-end; justify-content:center; background:#04060aaa; }
.dialog-box { width:100%; max-width:520px; display:flex; gap:10px; background:linear-gradient(180deg,#161d33,#0c1120); border:1px solid #3a4f7e; border-radius:16px 16px 0 0; padding:14px; animation:slideup .18s; }
.dialog-portrait { width:64px; height:64px; font-size:34px; display:flex; align-items:center; justify-content:center; background:#0b0f1c; border:1px solid #3a4f7e; border-radius:12px; flex-shrink:0; }
.dialog-main { flex:1; display:flex; flex-direction:column; min-width:0; }
.dialog-name { font-weight:900; color:#ffd77a; font-size:14px; }
.dialog-text { font-size:12px; color:#c7d4ef; line-height:1.5; margin:5px 0 9px; }
.dialog-opts { display:flex; flex-direction:column; gap:6px; }
.dlg-opt { text-align:left; padding:10px 12px; border-radius:10px; background:#182238; border:1px solid #31446b; font-size:13px; font-weight:700; color:#cfe1ff; }
.dlg-opt:active { background:#2c3d6e; }
.dlg-opt.q { border-color:#5fd35f; } .dlg-opt.exit { color:#8fa4cf; }

/* hero cards / misc ui text */
.hero-panel .big-stat { text-align:center; margin-bottom:10px; }
.portrait-big { width:84px; height:84px; border-radius:50%; background:#0b0f1c; border:2px solid #ffd77a; margin:0 auto 8px; display:flex; align-items:center; justify-content:center; overflow:hidden; }
.stat-grid { display:grid; grid-template-columns:1fr 1fr; gap:6px 12px; font-size:12px; background:#101828; border:1px solid #263450; border-radius:12px; padding:12px; }
.stat-grid span { color:#8fa4cf; } .stat-grid b { color:#fff; text-align:right; }
.divider { height:1px; background:#263450; margin:10px 0; }
.sec-title { font-size:12px; font-weight:900; letter-spacing:1px; color:#9db1d8; margin:10px 0 6px; }
.btn { padding:10px 14px; border-radius:10px; font-weight:800; font-size:13px; }
.btn-row { display:flex; gap:8px; flex-wrap:wrap; }
.center { text-align:center; }
small.hint { color:#7d91bd; font-size:10px; display:block; line-height:1.5; }
.qobj { font-size:11px; line-height:1.6; }
.qobj.done { color:#5fd35f; }
.qcard { background:#101828; border:1px solid #263450; border-radius:12px; padding:10px 12px; margin-bottom:8px; }
.qcard.tracked { border-color:#ffd77a99; }
.qname { font-weight:800; font-size:13px; color:#ffd77a; }
.qdesc { font-size:11px; color:#9db1d8; line-height:1.45; margin:3px 0 5px; }
.qrew { font-size:10px; color:#8ff5a8; }
@media (max-height:640px){ .joy-base{width:92px;height:92px} .abtn.attack{width:76px;height:76px} .abtn.skill{width:64px;height:64px} }

