  // creates a stat block for an item
  function makeItem(opts) {
    const { slot, cls = 'any', lvl, tier = 3, rarity = 'Common', stone = null, name = null } = opts;
    const P = powerAt(lvl) * TIER_MULT[tier] * RARITY_MULT[rarity];
    let stats = {}, nameBase;
    const armor = classArmorNames[cls] || 'Wanderer';
    switch (slot) {
      case 'weapon': nameBase = `${TIER_PREFIX[tier]} ${cls === 'any' ? '' : ''}${weaponBase[cls]}`; stats = { atk: Math.round(P * 1.15), crit: +(0.012 * (TIER_MULT[tier] * RARITY_MULT[rarity])).toFixed(3) }; break;
      case 'head': nameBase = `${armor} Helm`; stats = { hp: Math.round(P * 3.2), def: Math.round(P * 0.35) }; break;
      case 'chest': nameBase = `${armor} Mail`; stats = { def: Math.round(P * 0.8), hp: Math.round(P * 2.8) }; break;
      case 'hands': nameBase = `${armor} Gauntlets`; stats = { atk: Math.round(P * 0.3), critDmg: Math.round(4 * TIER_MULT[tier] * RARITY_MULT[rarity]) }; break;
      case 'legs': nameBase = `${armor} Greaves`; stats = { hp: Math.round(P * 2.4), def: Math.round(P * 0.45) }; break;
      case 'feet': nameBase = `${armor} Sabatons`; stats = { spd: (TIER_MULT[tier] * RARITY_MULT[rarity] > 1.3 ? 2 : 1), def: Math.round(P * 0.3) }; break;
      case 'ring': nameBase = miscBase.ring; stats = { crit: +(0.03 * TIER_MULT[tier] * RARITY_MULT[rarity]).toFixed(3), atk: Math.round(P * 0.45) }; break;
      case 'amulet': nameBase = miscBase.amulet; stats = { hp: Math.round(P * 2.0), mp: Math.round(P * 1.4) }; break;
      case 'cloak': nameBase = miscBase.cloak; stats = { def: Math.round(P * 0.5), hp: Math.round(P * 1.1) }; break;
    }
    if (name) nameBase = name;
    const bonuses = stone ? stone.bonuses.map(b => ({ ...b })) : [];
    const item = {
      uid: 'i' + Math.random().toString(36).slice(2, 10),
      kind: 'gear', slot, cls, lvl, tier, rarity, name: nameBase,
      stats, bonuses, icon: SLOT_ICON[slot], clan: stone ? stone.src : null
    };
    item.value = Math.max(5, Math.round(Math.pow(P, 1.55) / 2));
    return item;
  }

