/* AETHERIA dev harness: loads the game in mobile-size Chromium,
   clicks through flows, captures small JPEG screenshots. */
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');

(async () => {
  const args = process.argv.slice(2);
  const shot = args[0] || 'menu';
  const script = args[1] || '';
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--use-gl=swiftshader', '--enable-unsafe-swiftshader']
  });
  const page = await browser.newPage({
    viewport: { width: 390, height: 844 },
    isMobile: true, hasTouch: true,
    deviceScaleFactor: 1
  });
  page.on('console', m => { if (m.type() === 'error') console.log('PAGE-ERR:', m.text()); });
  page.on('pageerror', e => console.log('PAGE-EXC:', e.message));
  await page.goto('http://localhost:8765/', { waitUntil: 'load' });
  await page.waitForTimeout(2600); // loading screen

  const runShots = async () => {
    await page.screenshot({ path: `/tmp/opencode/shots/${shot}.jpg`, type: 'jpeg', quality: 62 });
    console.log('SAVED', shot);
  };

  if (script === 'create') {
    // open creation + walk through to gameplay
    await page.click('#btnNewGame');
    await page.waitForTimeout(300);
    await page.fill('#ccName', 'Aeolian');
    await page.screenshot({ path: '/tmp/opencode/shots/create1.jpg', type: 'jpeg', quality: 62 });
    await page.click('#btnCreateNext');
    await page.waitForTimeout(300);
    await page.click('[data-fc="demon"]');
    await page.screenshot({ path: '/tmp/opencode/shots/create2.jpg', type: 'jpeg', quality: 62 });
    await page.click('#btnCreateNext');
    await page.waitForTimeout(300);
    await page.click('[data-cl="assassin"]');
    await page.screenshot({ path: '/tmp/opencode/shots/create3.jpg', type: 'jpeg', quality: 62 });
    await page.click('#btnCreateNext');
    await page.waitForTimeout(300);
    await page.click('[data-h="3"]');
    await page.waitForTimeout(600);
    await page.screenshot({ path: '/tmp/opencode/shots/create4.jpg', type: 'jpeg', quality: 62 });
    await page.click('#btnCreateNext');
    await page.waitForTimeout(2500);
    console.log('IN-WORLD');
  }

  if (script === 'play') {
    // verify world rendered for 2.5s then interact checks
    await page.waitForTimeout(2200);
    console.log('STATE:', await page.evaluate(() => {
      const s = window.Game && Game.state; const p = Game.player();
      return s ? `char=${s.char.name} lvl=${s.char.lvl} cls=${s.char.cls} region=${s.world.regionId} pos=${p.x.toFixed(1)},${p.y.toFixed(1)} hp=${Math.round(p.hp)}` : 'NO STATE';
    }));
  }

  await runShots();
  await browser.close();
})().catch(e => { console.error('HARNESS-ERR', e.message); process.exit(1); });

