/* AETHERIA functional test suite: drives the real game and asserts systems */
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const shots = '/tmp/opencode/shots';
const out = [];
const log = (k, v) => { out.push(`${k}: ${v}`); console.log(`${k}: ${v}`); };

(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  const errs = [];
  page.on('pageerror', e => errs.push(e.message));
  await page.goto('http://localhost:8765/?t=' + Date.now(), { waitUntil: 'load' });
  await page.waitForTimeout(2400);

  // boot fresh mage+angel via the same path as startGame
  await page.evaluate(() => {
    localStorage.removeItem(Game.SAVE_KEY);
    document.getElementById('menuScreen').classList.add('hidden');
    document.getElementById('gameScreen').classList.remove('hidden');
    Game.bootNew('Seraphine', { gender: 'female', hair: 1, hairCol: '#e8d9a0', eye: '#3db0a8', outfit: 0, cls: 'mage', faction: 'angel' });
    UI.currency(); UI.potionCounts();
    const s = Game.state;
    document.getElementById('btnAuto').classList.toggle('on', s.settings.autoAttack);
  });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: shots + '/f1_town.jpg', type: 'jpeg', quality: 60 });

  // ---- movement (keyboard) ----
  const pos0 = await page.evaluate(() => { const p = Game.player(); return [p.x, p.y]; });
  await page.keyboard.down('w');
  await page.waitForTimeout(800);
  await page.keyboard.up('w');
  const pos1 = await page.evaluate(() => { const p = Game.player(); return [p.x, p.y]; });
  log('MOVEMENT', (pos1[1] < pos0[1] - 0.5) ? 'PASS' : `FAIL ${pos0} -> ${pos1}`);
  await page.screenshot({ path: shots + '/f2_moved.jpg', type: 'jpeg', quality: 60 });

  // ---- combat: teleport to a spawn cluster ----
  await page.evaluate(() => {
    const sp = Game.region().spawns.find(s => s.type === 'mob');
    const p = Game.player();
    p.x = sp.x + .5; p.y = sp.y + .5; p.hp = Game.playerStats().hp; p.mp = 200;
  });
  await page.waitForTimeout(2600);
  const combat = await page.evaluate(() => {
    const s = Game.state;
    const dead = Game.monsters().filter(m => m.dead).length;
    return { dead, inv: s.inv.length, xp: s.char.xp, hp: Math.round(Game.player().hp), gold: s.acct.gold };
  });
  log('COMBAT', combat.dead > 0 ? `PASS (${combat.dead} kills, xp=${combat.xp}, inv=${combat.inv}, gold=${combat.gold})` : `FAIL no kills HP=${combat.hp}`);
  await page.screenshot({ path: shots + '/f3_combat.jpg', type: 'jpeg', quality: 60 });

  // ---- skill usage ----
  const skillOk = await page.evaluate(() => {
    Game.player().mp = 200;
    Game.useSkill();
    return Game.player().skillCd > 0 || Game.player().mp < 200;
  });
  log('SKILL', skillOk ? 'PASS' : 'FAIL');
  await page.waitForTimeout(700);
  await page.screenshot({ path: shots + '/f4_skill.jpg', type: 'jpeg', quality: 60 });

  // ---- potions ----
  const pot = await page.evaluate(() => {
    const s = Game.state, before = s.potions.hp;
    Game.player().hp = 10;
    const r = Game.drinkPotion('hp');
    return { r, before, after: s.potions.hp, hp: Math.round(Game.player().hp) };
  });
  log('POTION', (pot.r === 'ok' && pot.after === pot.before - 1 && pot.hp > 50) ? `PASS (${pot.hp} hp)` : `FAIL ${JSON.stringify(pot)}`);

  // ---- inventory panel ----
  await page.evaluate(() => UI.openPanel('inv'));
  await page.waitForTimeout(300);
  await page.screenshot({ path: shots + '/f5_inv.jpg', type: 'jpeg', quality: 60 });
  await page.evaluate(() => { UI.closePanel(); });

  // ---- equip from inventory ----
  const eq = await page.evaluate(() => {
    const s = Game.state;
    const D = window.DATA;
    const it = D.makeItem({ slot: 'ring', cls: 'any', lvl: 4, tier: 3, rarity: 'Green' });
    s.inv.push(it);
    Game.equipItem(it.uid);
    return { equipped: !!s.equip.ring, crit: Game.playerStats().crit };
  });
  log('EQUIP', eq.equipped ? `PASS (crit ${(eq.crit * 100).toFixed(1)}%)` : 'FAIL');

  // ---- fusion: 4 identical T3 -> T2 ----
  const fuse = await page.evaluate(() => {
    const D = window.DATA;
    for (let i = 0; i < 4; i++) Game.state.inv.push(D.makeItem({ slot: 'feet', cls: 'any', lvl: 5, tier: 3, rarity: 'Grey' }));
    const key = Game.state.inv.filter(i => i.kind === 'gear' && i.slot === 'feet' && i.rarity === 'Grey')[0];
    const out = Game.fuseGroup(Game.keyOf(key));
    return out ? { tier: out.tier, rarity: out.rarity, name: out.name } : null;
  });
  log('FUSION_T3_T2', (fuse && fuse.tier === 2) ? `PASS (${fuse.name} T2 ${fuse.rarity})` : 'FAIL');

  const fuse2 = await page.evaluate(() => {
    const D = window.DATA;
    for (let i = 0; i < 4; i++) Game.state.inv.push(D.makeItem({ slot: 'ring', cls: 'any', lvl: 6, tier: 1, rarity: 'Blue' }));
    const key = Game.state.inv.filter(i => i.kind === 'gear' && i.slot === 'ring' && i.rarity === 'Blue' && i.tier === 1)[0];
    const out = Game.fuseGroup(Game.keyOf(key));
    return out ? { tier: out.tier, rarity: out.rarity } : null;
  });
  log('FUSION_T1_NEXTRARITY', (fuse2 && fuse2.tier === 3 && fuse2.rarity === 'Purple') ? `PASS (T3 ${fuse2.rarity})` : 'FAIL');

  // ---- legendary crafting ----
  const craft = await page.evaluate(() => {
    const D = window.DATA;
    const r = D.RECIPES.find(x => x.cls === Game.state.char.cls);
    Object.entries(r.mats).forEach(([id, n]) => Game.state.materials[id] = n);
    const stone = D.bossStone({ name: 'Test', label: 'Test', lvl: 20 });
    Game.state.inv.push(stone);
    Game.state.acct.gold += 5000;
    const out = Game.craftRecipe(r, stone);
    return out ? { name: out.name, rarity: out.rarity, bonuses: out.bonuses.length } : null;
  });
  log('LEGENDARY_CRAFT', (craft && craft.rarity === 'Legendary') ? `PASS (${craft.name}, ${craft.bonuses} stone bonuses)` : 'FAIL');

  // ---- quest flow ----
  const quest = await page.evaluate(() => {
    Game.state.kills['Meadow Slime'] = 8;
    Game.questEvent('kill', 'Meadow Slime');
    const q = Game.state.quests.active['m1'];
    return q && q.done;
  });
  log('QUEST_TRACK', quest ? 'PASS' : 'FAIL');

  // ---- shop buy ----
  const shop = await page.evaluate(() => {
    Game.state.acct.gems = 500; Game.state.acct.gold = 50000;
    const m = window.DATA.SHOP.mounts[0];
    const ok = Game.buyShop(m);
    const summoned = Game.toggleCosmetic('mount', m.id) === undefined && Game.player().mountOn;
    return { ok, summoned };
  });
  log('SHOP_MOUNT', (shop.ok && shop.summoned) ? 'PASS' : 'FAIL');

  // ---- market ----
  const mkt = await page.evaluate(() => {
    Game.marketTick();
    const listings = Game.state.market.listings.length;
    // list an item
    const it = window.DATA.makeItem({ slot: 'cloak', cls: 'any', lvl: 10, tier: 3, rarity: 'Green' });
    Game.state.inv.push(it);
    Game.marketListItem(it.uid, 500);
    return { listings, mine: Game.state.market.mine.length };
  });
  log('MARKET', (mkt.listings > 0 && mkt.mine === 1) ? 'PASS' : `FAIL ${JSON.stringify(mkt)}`);

  // ---- storage ----
  const stor = await page.evaluate(() => {
    const it = window.DATA.makeItem({ slot: 'ring', cls: 'any', lvl: 8, tier: 3, rarity: 'Grey' });
    Game.state.inv.push(it);
    Game.deposit(it.uid);
    const inStore = Game.state.storage.length === 1;
    Game.withdraw(Game.state.storage[0].uid);
    return { inStore, back: Game.state.inv.includes(Game.state.storage[0]) || Game.state.inv.some(i => i.uid === it.uid) };
  });
  log('STORAGE', (stor.inStore && stor.back) ? 'PASS' : 'FAIL');

  // ---- portals / regions ----
  const tele = await page.evaluate(() => {
    const wd = World.build('ironcrag');
    return Game.doTeleport ? 'n/a' : Game.teleportTo('ironcrag');
  });
  const regionNow = await page.evaluate(() => Game.state.world.regionId);
  log('TRAVEL', (tele && regionNow === 'ironcrag') ? `PASS (${regionNow})` : `FAIL ${regionNow}`);

  await page.waitForTimeout(1400);
  await page.screenshot({ path: shots + '/f6_ironcrag.jpg', type: 'jpeg', quality: 60 });

  // ---- tower gate locked without key ----
  const towerLock = await page.evaluate(() => {
    return Game.teleportTo('tower') === false;
  });
  log('TOWER_LOCKED', towerLock ? 'PASS' : 'FAIL');

  // ---- save / restore ----
  const saved = await page.evaluate(() => { Game.save(); return Game.state.char.name; });
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(2400);
  const cont = await page.evaluate(() => {
    const s = Game.load();
    return s ? s.char.name : null;
  });
  log('SAVE_LOAD', cont === saved ? `PASS (${cont})` : `FAIL ${cont} vs ${saved}`);
  // continue button flow
  await page.click('#btnContinue');
  await page.waitForTimeout(1200);
  const backOk = await page.evaluate(() => Game.isLoaded() && !!Game.player());
  log('CONTINUE', backOk ? 'PASS' : 'FAIL');
  await page.screenshot({ path: shots + '/f7_continued.jpg', type: 'jpeg', quality: 60 });

  console.log('ERRORS_ON_PAGE:', errs.length ? errs.slice(0, 5).join(' | ') : 'none');
  await browser.close();
})().catch(e => { console.error('HARNESS-ERR', e); process.exit(1); });

