function questEvent(type, target) {
  let anyDone = false;
  for (const q of activeQuests()) {
    if (G.quests.active[q.id].done) continue;
    q.objs.forEach((o, i) => {
      const qs = G.quests.active[q.id];
      if (qs.p[i] >= o.n) return;
      let bump = false;
      if (o.type === 'kill' && type === 'kill') {
        // recomputed from the kill ledger
