    G.acct.gold -= fee;
    enterRegion(regionId, wd.town ? { x: wd.town.x + .5, y: wd.town.y + 2.5 } : { x: Math.floor(wd.w / 2) + .5, y: Math.floor(wd.h / 2) + .5 });
    save();
  }
  return true;
}

