/* AETHERIA deep test: boss kill, drop distribution, dialog turn-in, pets, premium, death loop */
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const shots = '/tmp/opencode/shots';
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  const errs = [];
  page.on('pageerror', e => errs.push(e.message));
  await page.goto('http://localhost:8765/?d=' + Date.now(), { waitUntil: 'load' });
  await page.waitForTimeout(2400);
  await page.evaluate(() => {
    localStorage.removeItem(Game.SAVE_KEY);
    document.getElementById('menuScreen').classList.add('hidden');
    document.getElementById('gameScreen').classList.remove('hidden');
    Game.bootNew('Seraphine', { gender: 'female', hair: 1, hairCol: '#e8d9a0', eye: '#3db0a8', outfit: 0, cls: 'mage', faction: 'angel' });
    UI.currency(); UI.potionCounts();
  });
  await page.waitForTimeout(800);

  // ---- statistical drop-rate check (pure logic) ----
  const rates = await page.evaluate(() => {
    const D = window.DATA;
    const buckets = {};
    for (let i = 0; i < 20000; i++) {
      const r = D.rollDropRarity();
      buckets[r] = (buckets[r] || 0) + 1;
    }
    return Object.fromEntries(Object.entries(buckets).map(([k, v]) => [k, (v / 200).toFixed(1)]));
  });
  console.log('DROP_SHARES% (target C60 G25 Gr10 Bl5):', JSON.stringify(rates));

  // ---- boss kill flow ----
  await page.evaluate(() => {
    const p = Game.player(), wd = Game.region();
    p.x = wd.arena.x; p.y = wd.arena.y + 1;
    Game.state.acct.gems = 0;
  });
  await page.waitForTimeout(1200);
  const bossUp = await page.evaluate(() => {
    const b = Game.monsters().find(m => m.boss && !m.dead);
    return b ? b.name : null;
  });
  console.log('BOSS_SPAWNED:', bossUp);
  // kill it fast (attack burst)
  await page.evaluate(() => {
    const b = Game.monsters().find(m => m.boss && !m.dead);
    if (b) { b.hp = 1; Game.playerAttack(); }
  });
  await page.waitForTimeout(500);
  const bossOut = await page.evaluate(() => {
    const s = Game.state;
    return {
      stones: s.inv.filter(i => i.kind === 'stone').length,
      gems: s.acct.gems,
      bossKills: JSON.stringify(s.bossKills),
      inv: s.inv.length
    };
  });
  console.log('BOSS_REWARDS:', JSON.stringify(bossOut));
  await page.screenshot({ path: shots + '/b1_afterboss.jpg', type: 'jpeg', quality: 60 });

  // ---- quest turn-in via dialog ----
  await page.evaluate(() => {
    const p = Game.player(), wd = Game.region();
    const rowan = wd.npcs.find(n => n.keyId === 'rowan');
    p.x = rowan.x + .6; p.y = rowan.y + .4;
  });
  await page.waitForTimeout(700);
  await page.evaluate(() => UI.openDialog(Game.region().npcs.find(n => n.keyId === 'rowan')));
  await page.waitForTimeout(400);
  await page.screenshot({ path: shots + '/b2_dialog.jpg', type: 'jpeg', quality: 60 });
  const turnIn = await page.evaluate(() => {
    const ts = Game.turnableQuestsFor('rowan');
    const res = [];
    ts.forEach(q => { Game.turnInQuest(q); res.push(q.id); });
    return { turnedIn: res, done: Game.state.quests.done, lvl: Game.state.char.lvl, gold: Game.state.acct.gold, gems: Game.state.acct.gems };
  });
  console.log('TURN_IN:', JSON.stringify(turnIn));

  // ---- faction wings quest ----
  await page.evaluate(() => {
    const w = window.DATA.QUESTS.find(q => q.id === 'w1');
    w.objs.forEach((o, i) => Game.state.active = null);
    // simulate completion
    Game.acceptQuest(w);
    const qs = Game.state.quests.active['w1'];
    w.objs.forEach(o => { Game.state.kills[o.target] = o.n; });
    Game.questEvent('kill', w.objs[0].target);
    Game.questEvent('kill', w.objs[1].target);
    Game.questEvent('kill', w.objs[2].target);
  });
  const wings = await page.evaluate(() => {
    const s = Game.state, q = s.quests.active['w1'];
    if (!q || !q.done) return null;
    Game.turnInQuest(window.DATA.QUESTS.find(x => x.id === 'w1'));
    return { unlocked: s.unlocked.wings, using: s.using.wings };
  });
  console.log('WINGS:', JSON.stringify(wings));

  // ---- equip wings + pet + fx visual ----
  await page.evaluate(() => {
    const s = Game.state;
    if (s.unlocked.wings.length) Game.toggleCosmetic('wings', s.unlocked.wings[0]);
    s.acct.gems = 300; s.acct.gold = 50000;
    Game.buyShop({ id: 'pe_wisp', name: 'Sprite Wisp', icon: '🫧', gold: 2500, perk: 'Pickup', type: 'pet' });
    Game.toggleCosmetic('pet', 'pe_wisp');
    Game.buyShop({ id: 'fx_frost', name: 'Frost Trail', icon: '❄️', gems: 20, type: 'fx' });
    Game.toggleCosmetic('fx', 'fx_frost');
  });
  await page.waitForTimeout(900);
  await page.screenshot({ path: shots + '/b3_cosmetics.jpg', type: 'jpeg', quality: 60 });

  // ---- premium ----
  const prem = await page.evaluate(() => {
    Game.state.acct.gems = 200;
    const ok = Game.buyShop({ ...window.DATA.SHOP.premium, type: 'premium' });
    return { ok, active: Game.state.acct.premium > Date.now() };
  });
  console.log('PREMIUM:', JSON.stringify(prem));

  // ---- death & respawn ----
  await page.evaluate(() => {
    const p = Game.player();
    p.x = 20; p.y = 30; p.hp = 1;
    Game.state.settings.autoAttack = false;
  });
  await page.waitForTimeout(600);
  await page.evaluate(() => {
    const p = Game.player();
    p.hp = 0;
  });
  await page.waitForTimeout(3800);
  const resp = await page.evaluate(() => {
    const p = Game.player(), wd = Game.region();
    return { dead: p.dead, hp: Math.round(p.hp), atTown: wd.town ? Math.hypot(p.x - wd.town.x, p.y - wd.town.y) < 4 : 'no-town' };
  });
  console.log('RESPAWN:', JSON.stringify(resp));

  // ---- drop-item pickup + equip validation (class restriction) ----
  await page.evaluate(() => {
    const D = window.DATA;
    const wrong = D.makeItem({ slot: 'weapon', cls: 'warrior', lvl: 3, tier: 3, rarity: 'Common' });
    const right = D.makeItem({ slot: 'weapon', cls: 'mage', lvl: 3, tier: 3, rarity: 'Blue' });
    Game.state.inv.push(wrong, right);
    window.__eqTest = { wrongBlocked: false, rightWorn: false };
    const s = Game.state;
    const prev = s.equip.weapon;
    Game.equipItem(wrong.uid);
    window.__eqTest.wrongBlocked = s.equip.weapon !== wrong;
    Game.equipItem(right.uid);
    window.__eqTest.rightWorn = s.equip.weapon === right;
    s.equip.weapon = prev;
  });
  console.log('CLASS_RESTRICT:', JSON.stringify(await page.evaluate(() => window.__eqTest)));

  // ---- skill upgrade ----
  const sk = await page.evaluate(() => {
    const s = Game.state;
    s.char.skillPts = 2; s.acct.gold = 30000;
    Game.upgradeSkill();
    return { lvl: s.char.skillLvl, pts: s.char.skillPts };
  });
  console.log('SKILL_UP:', JSON.stringify(sk));

  console.log('ERRORS:', errs.length ? errs.slice(0, 6).join(' | ') : 'none');
  await browser.close();
})().catch(e => { console.error('HARNESS-ERR', e.message); process.exit(1); });

