const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const shots = '/tmp/opencode/shots';
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  const errs = [];
  page.on('pageerror', e => errs.push(e.message + ' @' + (e.stack || '').split('\n').slice(1, 3).join('|')));
  await page.goto('http://localhost:8765/?c=' + Date.now(), { waitUntil: 'load' });
  await page.waitForTimeout(2400);
  await page.evaluate(() => {
    localStorage.removeItem(Game.SAVE_KEY);
    document.getElementById('menuScreen').classList.add('hidden');
    document.getElementById('gameScreen').classList.remove('hidden');
    Game.bootNew('Sterling', { gender: 'male', hair: 2, cls: 'warrior', faction: 'demon' });
    const s = Game.state; s.settings.autoAttack = true;
    UI.currency(); UI.potionCounts();
  });
  await page.waitForTimeout(700);

  // kill 8 slimes via auto-attack (long session near a spawn cluster)
  await page.evaluate(() => {
    const sp = Game.region().spawns.find(s => s.type === 'mob');
    const p = Game.player();
    p.x = sp.x + 1.1; p.y = sp.y + 1.1;
    p.hp = p.maxhp; p.mp = 200;
  });
  await page.waitForTimeout(15000);
  const hunt = await page.evaluate(() => {
    const s = Game.state;
    return { kills: s.kills, questM1: s.quests.active['m1'], lvl: s.char.lvl, xp: s.char.xp, gold: s.acct.gold, inv: s.inv.length, potions: s.potions, mats: s.materials };
  });
  console.log('GRAIND:', JSON.stringify(hunt));
  await page.screenshot({ path: shots + '/c1_grind.jpg', type: 'jpeg', quality: 60 });

  // turn m1 in at rowan
  const turn = await page.evaluate(() => {
    const p = Game.player(), wd = Game.region();
    const rowan = wd.npcs.find(n => n.keyId === 'rowan');
    p.x = rowan.x + .6; p.y = rowan.y + .8;
    const before = Game.state.acct.gold;
    const ts = Game.turnableQuestsFor('rowan').map(q => q.id);
    ts.forEach(id => Game.turnInQuest(window.DATA.QUESTS.find(q => q.id === id)));
    return { turned: ts, gold: Game.state.acct.gold - before, accepted: Object.keys(Game.state.quests.active) };
  });
  console.log('TURNIN:', JSON.stringify(turn));

  // boss stones pickup: position on boss after kill
  await page.evaluate(() => {
    const p = Game.player(), wd = Game.region();
    p.x = wd.arena.x - 1; p.y = wd.arena.y - 1; p.hp = p.maxhp; p.mp = p.maxmp;
    Game.state.char.lvl = 12; // fair fight
    UI.currency();
  });
  await page.waitForTimeout(1300);
  await page.evaluate(() => {
    const b = Game.monsters().find(m => m.boss && !m.dead);
    if (b) { b.hp = 2; Game.playerAttack(); }
  });
  await page.waitForTimeout(2500);
  const stones = await page.evaluate(() => {
    const s = Game.state;
    return { stones: s.inv.filter(i => i.kind === 'stone').map(x => x.name + '[' + x.bonuses.length + 'b]'), killCount: s.bossKills, onGround: Game.drops().filter(d => d.item).length, dead: s.char ? Game.monsters().filter(m => m.boss && m.dead).length : 0 };
  });
  console.log('STONES:', JSON.stringify(stones));
  await page.screenshot({ path: shots + '/c2_stones.jpg', type: 'jpeg', quality: 60 });

  // death & respawn (properly: let a monster kill us inside aggro)
  const resp = await page.evaluate(() => {
    const p = Game.player();
    const m0 = Game.monsters().find(x => !x.dead && !x.boss && x.atk > 0);
    p.x = m0.x - .8; p.y = m0.y; p.hp = 1;
    return 'set';
  });
  await page.waitForTimeout(5200);
  const respawn = await page.evaluate(() => {
    const p = Game.player(), wd = Game.region();
    return { dead: p.dead, hp: Math.round(p.hp), distTown: wd.town ? ((Math.abs(p.x - wd.town.x) + Math.abs(p.y - wd.town.y)).toFixed(1)) : 'n/a' };
  });
  console.log('RESPAWN:', JSON.stringify(respawn));
  console.log('ERRORS:', errs.length ? errs.slice(0, 6).join(' | ') : 'none');
  await browser.close();
})().catch(e => { console.error('HARNESS-ERR', e.message); process.exit(1); });

