  page.on('pageerror', e => errs.push(e.message + ' @' + (e.stack || '').split('\n').slice(1, 3).join('|')));
  await page.goto('http://localhost:8765/?c=' + Date.now(), { waitUntil: 'load' });
  await page.waitForTimeout(2400);
  await page.evaluate(() => {
    localStorage.removeItem(Game.SAVE_KEY);
    document.getElementById('menuScreen').classList.add('hidden');
    document.getElementById('gameScreen').classList.remove('hidden');
    Game.bootNew('Bossman', { gender: 'male', hair: 2, cls: 'warrior', faction: 'demon' });
    const s = Game.state; s.settings.autoAttack = false;
    UI.currency(); UI.potionCounts();
  });
  await page.waitForTimeout(600);

  // go to arena, level up to 12, spawn boss by proximity
  await page.evaluate(() => {
    const p = Game.player(), wd = Game.region();
    p.x = wd.arena.x - 1; p.y = wd.arena.y - 1; p.hp = p.maxhp; p.mp = p.maxmp;
    Game.state.char.lvl = 12;
  });
  await page.waitForTimeout(1500);
  const spawned = await page.evaluate(() => Game.monsters().filter(m => m.boss).map(m => m.name + ' hp:' + m.hp));
  console.log('SPAWNED:', JSON.stringify(spawned));

  // finish the boss deterministically
  await page.evaluate(() => {
    const b = Game.monsters().find(m => m.boss && !m.dead);
    if (b) { b.hp = 2; Game.playerAttack(); }
  });
  await page.waitForTimeout(1200);
  const killState = await page.evaluate(() => {
    const s = Game.state;
    return {
      bossDead: Game.monsters().filter(m => m.boss && m.dead).length,
      bossKills: s.bossKills,
      ground: Game.drops().map(d => d.item ? d.item.rarity + ':' + d.item.slot : (d.gold !== undefined ? 'gold' : 'mat'))
    };
  });
  console.log('KILL:', JSON.stringify(killState));

  // walk onto each item drop using the vacuum radius
  await page.evaluate(() => {
    const p = Game.player();
    Game.state.settings.autoAttack = false;
    p.hp = p.maxhp; p.mp = p.maxmp; p.dead = false;
  });
  const pickups = [];
  for (let i = 0; i < 6; i++) {
    const spot = await page.evaluate(() => {
      const p = Game.player();
      const d = Game.drops().find(d => (d.item || d.matShow) && d.t > .3);
      if (!d) return null;
      p.x = d.x; p.y = d.y;
      return { x: Math.round(d.x * 10) / 10, y: Math.round(d.y * 10) / 10 };
    });
    if (!spot) break;
    await page.waitForTimeout(420);
    pickups.push(spot);
  }
  await page.waitForTimeout(600);
  const picked = await page.evaluate(() => {
    const s = Game.state;
    return {
      stones: s.inv.filter(i => i.kind === 'stone').map(x => x.name + ' [' + x.bonuses.length + 'b]'),
      gear: s.inv.filter(i => i.kind === 'equip').length,
      killCount: s.bossKills,
      onGround: Game.drops().filter(d => d.item).length,
      potions: s.potions
    };
  });
  console.log('PICKED:', JSON.stringify(picked));
  await page.screenshot({ path: shots + '/d1_bosswin.jpg', type: 'jpeg', quality: 60 });

  // inspect a stone's bonuses in detail
  const stone = await page.evaluate(() => {
    const st = Game.state.inv.find(i => i.kind === 'stone');
    return st ? { name: st.name, tier: st.tier, rarity: st.rarity, bonuses: st.bonuses } : null;
  });
  console.log('STONE:', JSON.stringify(stone));

  console.log('ERRORS:', errs.length ? errs.slice(0, 6).join(' | ') : 'none');
  await browser.close();
})().catch(e => { console.error('HARNESS-ERR', e.stack || e.message); process.exit(1); });

